"""R16: lecturas originales y evidencia explícita para cada respuesta."""
import json
from pathlib import Path
U=[]
def unit(id,after,title,exp,hint,rows):
 activities=[]
 for i,(story,q,answer,quote,why,wrong1,wrong2) in enumerate(rows):
  assert quote in story,(id,quote)
  options=[answer,wrong1,wrong2];assert len(set(options))==3
  k=i%3;options=options[k:]+options[:k]
  activities.append(dict(id=id+'-v'+str(i+1),enunciado=q,respuesta_correcta=answer,opciones=options,paso_resuelto='El texto dice «'+quote+'». '+why,visual=dict(tipo='lectura',titulo='Texto para releer',texto=story)))
 first=rows[0]
 U.append(dict(id=id,tema='comprension_lectora_literal_inferida',despues_de=after,titulo=title,explicacion=exp,ejemplo=first[1]+' '+first[2]+'.',pasos=['Buscamos la pista: «'+first[3]+'».',first[4]],pista=hint,visual=activities[0]['visual'],actividades=activities))
unit('leng_prof_precision','leng_lect_1_literal','Elegir el dato que responde a la pregunta','Primero miramos si la pregunta pide quién, dónde, cuándo o qué ocurrió. Puede haber varios datos parecidos. Seguimos al personaje y la acción nombrados; no elegimos un dato solo porque aparezca cerca. Podés volver al texto.', 'Buscá juntos el personaje y la acción de la pregunta.',[
('El martes, Vera pidió un libro en la biblioteca. Lo leyó en casa durante dos días. El viernes regresó a la biblioteca para devolverlo.','¿Qué día devolvió Vera el libro?','El viernes','El viernes regresó a la biblioteca para devolverlo','El martes lo pidió; la devolución ocurrió el viernes.','El martes','El miércoles'),
('En el taller, Iván dejó las tijeras sobre la mesa y los lápices en un cajón. Después llevó su dibujo al patio para mostrárselo a su hermana.','¿Dónde dejó Iván los lápices?','En un cajón','los lápices en un cajón','El patio es el lugar al que llevó el dibujo, no los lápices.','Sobre la mesa','En el patio'),
('Para la merienda, Alma llevó pan y Bruno llevó fruta. La profesora puso agua en una jarra. Entre todos acomodaron los alimentos sobre una manta.','¿Quién llevó la fruta?','Bruno','Bruno llevó fruta','Buscamos a la persona asociada con la fruta.','Alma','La profesora'),
('El tren salió a las nueve. A las diez llegó a la estación del pueblo y allí subió Julia. Una hora después, Julia bajó en la estación del lago.','¿Dónde subió Julia al tren?','En la estación del pueblo','llegó a la estación del pueblo y allí subió Julia','La estación del lago es donde bajó.','En la estación del lago','El texto no lo indica'),
('Sofía preparó dos cajas. En la pequeña puso botones y en la grande guardó retazos. Luego pegó una etiqueta roja en la caja de los botones.','¿Qué guardó en la caja grande?','Retazos','en la grande guardó retazos','Los botones están en la pequeña.','Botones','Etiquetas rojas'),
('El sábado el club abrió el salón para pintar carteles. El domingo los vecinos se reunieron en la plaza para colgarlos. Los carteles anunciaban la feria del lunes.','¿Cuándo colgaron los carteles?','El domingo','El domingo los vecinos se reunieron en la plaza para colgarlos','La feria es el lunes; colgarlos fue una acción anterior.','El sábado','El lunes')])
unit('leng_prof_orden','leng_prof_precision','Reconstruir el orden de los hechos','Palabras como antes, después y al final ayudan a ordenar lo que pasó. El orden de las frases no siempre coincide con el de los hechos. Buscamos esas señales y reconstruimos el recorrido.', 'Prestá atención a antes y después: indican el orden real.',[
('Antes de sembrar, Leo llenó la maceta con tierra. Después colocó las semillas. Al final agregó agua y dejó la maceta junto a la ventana.','¿Qué hizo Leo primero?','Llenó la maceta con tierra','Antes de sembrar, Leo llenó la maceta con tierra','La palabra antes sitúa la tierra al comienzo.','Agregó agua','Colocó las semillas'),
('Cuando llegó al club, Sara guardó la bicicleta. Antes de salir de casa había revisado los frenos. Tras guardar la bicicleta, entró al salón.','¿Qué ocurrió antes de llegar al club?','Revisó los frenos','Antes de salir de casa había revisado los frenos','La revisión ocurrió en casa, aunque se cuente en la segunda frase.','Entró al salón','Guardó la bicicleta'),
('El grupo dibujó un mapa y luego marcó el camino. Antes de empezar a caminar, revisó las marcas. Finalmente salió del refugio.','¿Qué hizo justo después de dibujar el mapa?','Marcó el camino','dibujó un mapa y luego marcó el camino','Luego une esas dos acciones consecutivas.','Salió del refugio','Revisó las marcas'),
('Mica lavó las frutillas. Después las cortó y las puso en un bol. Solo cuando terminó de cortarlas agregó yogur.','¿Qué hizo Mica al final?','Agregó yogur','cuando terminó de cortarlas agregó yogur','El yogur se agregó después de lavar y cortar.','Lavó las frutillas','Cortó las frutillas'),
('Antes de pegar las piezas, Omar armó el rompecabezas sobre la mesa. Después de pegarlas, lo dejó secar. Al día siguiente lo colgó.','¿Qué hizo después de pegar las piezas y antes de colgar el trabajo?','Lo dejó secar','Después de pegarlas, lo dejó secar','Es la acción situada entre pegar y colgar.','Armó el rompecabezas','Lo colgó'),
('La clase visitó el museo el jueves. El miércoles había preparado preguntas. El viernes escribió un relato de la visita.','¿Cuál es el orden de esas actividades?','Preparar preguntas → visitar → escribir','El miércoles había preparado preguntas','Miércoles, jueves y viernes ordenan las tres actividades.','Visitar → preparar preguntas → escribir','Escribir → visitar → preparar preguntas')])
unit('leng_prof_referencias','leng_prof_orden','Reconocer de quién o de qué se habla','Para no repetir nombres, un texto puede usar palabras como ella, lo o allí. Volvemos a la frase anterior y probamos a qué se refieren. La sustitución debe conservar el sentido de la acción.', 'Reemplazá la palabra por el nombre y comprobá si la frase tiene sentido.',[
('Elena encontró un cuaderno bajo el banco. Lo abrió para buscar el nombre de su dueño. En la primera página había un teléfono.','¿A qué se refiere «Lo» en «Lo abrió»?','Al cuaderno','encontró un cuaderno','Lo que Elena abrió fue el cuaderno encontrado.','Al banco','Al teléfono'),
('El equipo llegó a la biblioteca. Allí revisó un atlas antes de comenzar el viaje. La bibliotecaria señaló una ruta en el mapa.','¿Qué lugar reemplaza «Allí»?','La biblioteca','El equipo llegó a la biblioteca','Revisar el atlas ocurrió en ese lugar.','El viaje','La ruta'),
('Clara llevó una manta al refugio. Ella quería que el cachorro tuviera un lugar cálido para dormir. La manta quedó junto a la puerta.','¿A quién se refiere «Ella»?','A Clara','Clara llevó una manta','Clara es la persona que quería ayudar al cachorro.','A la manta','A la puerta'),
('Tomás juntó las hojas secas del patio. Las puso en una bolsa para llevarlas al compost. Después barrió el camino.','¿Qué puso Tomás en la bolsa?','Las hojas secas','juntó las hojas secas','Las retoma las hojas mencionadas antes.','El camino','El patio'),
('Los vecinos se reunieron en el salón. Allí prepararon las mesas de la feria. Más tarde llevaron las mesas hasta la plaza.','¿Dónde prepararon las mesas?','En el salón','Los vecinos se reunieron en el salón','Allí remite al salón; a la plaza fueron después.','En la plaza','El texto no lo indica'),
('Inés eligió una novela del estante. La guardó en su mochila para leer durante el viaje. Al llegar, buscó un lugar tranquilo.','¿Qué reemplaza «La» en «La guardó»?','La novela','Inés eligió una novela','Inés guardó la novela; la mochila era el lugar donde la puso.','La mochila','La llegada')])
unit('leng_prof_contexto','leng_prof_referencias','Entender una palabra por lo que la rodea','Si una palabra no es familiar, leemos las frases cercanas. A veces describen lo mismo con otras palabras o muestran un contraste. Probamos el significado en la frase y elegimos el que encaja en ese contexto.', 'Buscá una descripción cercana que explique la palabra.',[
('Al entrar al patio, el gato se mostró cauteloso. Avanzó despacio, olfateó el suelo y miró a ambos lados antes de acercarse al plato.','¿Qué significa «cauteloso» en este texto?','Cuidadoso','Avanzó despacio, olfateó el suelo y miró a ambos lados','Las acciones muestran que el gato actuó con cuidado.','Apurado','Dormido'),
('El sendero era estrecho: dos personas no podían caminar una al lado de la otra. El grupo avanzó en fila hasta llegar al puente.','¿Qué significa «estrecho»?','Angosto','dos personas no podían caminar una al lado de la otra','Esa descripción explica que había poco ancho.','Muy largo','Resbaladizo'),
('La botella era transparente. Sin destaparla, Paula pudo ver el agua y las piedritas que estaban dentro. La puso frente a la ventana.','¿Qué significa «transparente» aquí?','Que deja ver a través','pudo ver el agua y las piedritas que estaban dentro','Paula veía el interior sin abrir la botella.','Que pesa mucho','Que no contiene nada'),
('El salón estaba desierto. No había nadie en las sillas ni junto al escenario. Bruno esperó cerca de la puerta hasta que llegó el grupo.','¿Qué significa «desierto» en este caso?','Sin personas','No había nadie en las sillas ni junto al escenario','Aquí describe un salón vacío de personas, no un paisaje.','Cubierto de arena','Con mucho ruido'),
('La explicación fue breve. Duró apenas dos minutos y presentó solo los pasos necesarios. Después todos empezaron a trabajar.','¿Qué significa «breve»?','Corta','Duró apenas dos minutos','La duración y la selección de pasos muestran que no fue extensa.','Difícil','Incompleta'),
('La planta recuperó su vigor. Sus tallos volvieron a estar firmes y aparecieron hojas nuevas. Luz siguió cuidándola durante la semana.','¿Qué significa «vigor» en este texto?','Fuerza','Sus tallos volvieron a estar firmes y aparecieron hojas nuevas','La firmeza y el crecimiento muestran que la planta recuperó fuerza.','Color rojo','Tamaño de la maceta')])
unit('leng_prof_causa','leng_prof_contexto','Entender causas, finalidades y consecuencias','Una causa explica por qué ocurrió algo; una finalidad indica para qué hacemos algo. Porque y por eso pueden señalar causas y consecuencias; para que presenta una finalidad. Buscamos la relación que indica el texto: no todo hecho anterior es la causa.', 'Preguntá qué hecho explica el resultado, no solo cuál sucedió antes.',[
('La lluvia llenó de agua la cancha. Por eso el partido se jugó dentro del gimnasio. Los equipos llegaron a la misma hora de siempre.','¿Por qué cambiaron el lugar del partido?','Porque la cancha estaba llena de agua','La lluvia llenó de agua la cancha. Por eso','Por eso conecta el estado de la cancha con el cambio de lugar.','Porque los equipos llegaron tarde','Porque cambiaron la hora'),
('El viento movía las hojas del cuaderno. Para que no se volaran, Nara puso una piedra encima. Luego siguió dibujando el árbol.','¿Para qué puso Nara una piedra sobre las hojas?','Para que no se volaran','Para que no se volaran, Nara puso una piedra encima','El texto expresa directamente la finalidad de la piedra.','Para borrar el dibujo','Para medir el árbol'),
('La linterna no encendía porque las pilas estaban gastadas. Al cambiarlas, volvió a funcionar. El grupo pudo seguir buscando la pelota.','¿Por qué no encendía la linterna?','Porque las pilas estaban gastadas','no encendía porque las pilas estaban gastadas','Porque introduce el motivo de la falla.','Porque habían encontrado la pelota','Porque era de noche'),
('El museo cerró una sala para reparar el techo. Por ese motivo, la guía eligió otro recorrido. La visita comenzó a horario.','¿Qué provocó el cambio de recorrido?','El cierre de una sala','El museo cerró una sala para reparar el techo. Por ese motivo','La reparación cerró la sala y obligó a cambiar el recorrido.','El comienzo puntual de la visita','La llegada de un grupo nuevo'),
('La maceta estaba lejos de la ventana y recibía poca luz. Por eso Juli la acercó al vidrio. Al moverla, dejó espacio libre en el estante.','¿Qué motivo tuvo Juli para mover la maceta?','Que recibiera más luz','recibía poca luz. Por eso Juli la acercó al vidrio','El espacio libre fue una consecuencia, no el motivo indicado.','Dejar lugar para un libro','Cambiar el color de la maceta'),
('El cartel tenía letras muy pequeñas y desde la puerta no se leía. Por eso el grupo lo rehízo con letras grandes. Usó la misma cartulina.','¿Por qué hicieron otro cartel?','Para que se pudiera leer desde la puerta','desde la puerta no se leía','Las letras grandes solucionaban ese problema.','Porque faltaba cartulina','Para cambiar el mensaje del cartel')])
unit('leng_prof_evidencia','leng_lect_2_inferencia','Justificar una inferencia con una pista','Una inferencia debe apoyarse en el texto. Después de elegir una explicación probable, buscamos la frase que la sostiene. Una frase puede ser verdadera y no servir como prueba de esa conclusión.', 'Elegí la pista que realmente apoya la conclusión propuesta.',[
('Lucía llegó al ensayo con la partitura. Mientras esperaba su turno, le temblaban las manos y respiraba muy rápido. Cuando la llamaron, se quedó un instante en silencio.','¿Qué pista apoya que Lucía probablemente estaba nerviosa?','Le temblaban las manos y respiraba rápido','le temblaban las manos y respiraba muy rápido','Esas reacciones apoyan nervios; llevar una partitura no los demuestra.','Llevaba una partitura','Había un ensayo'),
('El perro oyó la llave en la puerta. Corrió hacia ella moviendo la cola y dio pequeños saltos cuando entró su cuidador. Después se sentó junto a la mochila.','¿Qué pista apoya que el perro estaba contento por la llegada?','Movía la cola y daba pequeños saltos','moviendo la cola y dio pequeños saltos','Esas acciones apoyan la alegría al recibir al cuidador.','Había una mochila','La puerta tenía llave'),
('Al entrar, Marcos buscó el interruptor, pero la luz no encendió. Tampoco funcionaba la radio. Desde la ventana vio que la casa vecina estaba a oscuras.','¿Qué pista apoya un corte de electricidad en la zona?','Tampoco había luz en la casa vecina','la casa vecina estaba a oscuras','La falta de luz en otra casa apoya un problema más amplio.','Marcos miró por la ventana','Marcos conocía el interruptor'),
('Lara observó la tierra de la maceta: estaba seca y separada de los bordes. Tocó la superficie y no sintió humedad. Luego buscó la regadera.','¿Qué pista apoya que la planta probablemente necesitaba agua?','La tierra estaba seca y sin humedad','estaba seca y separada de los bordes','La sequedad de la tierra apoya la necesidad de agua.','Había una maceta','Lara tenía una regadera'),
('El reloj marcaba las seis. Simón cerraba los ojos, bostezaba y apoyaba la cabeza en el respaldo. Había esperado sentado durante un rato.','¿Qué pista apoya que Simón tenía sueño?','Cerraba los ojos y bostezaba','cerraba los ojos, bostezaba','Esas acciones apoyan sueño; la hora sola no lo demuestra.','Eran las seis','Había un reloj'),
('Vera revisó dos veces su mochila. Luego buscó bajo la mesa y preguntó si alguien había visto su estuche. Continuó mirando detrás de las sillas.','¿Qué pista apoya que Vera no encontraba el estuche?','Preguntó si alguien lo había visto','preguntó si alguien había visto su estuche','La pregunta y la búsqueda apoyan que no lo encontraba.','Había varias sillas','Vera tenía una mochila')])
unit('leng_prof_limites','leng_prof_evidencia','Reconocer lo que todavía no sabemos','Leer con cuidado también es reconocer un dato ausente. Podemos afirmar lo escrito y proponer inferencias apoyadas en pistas. Si preguntan una edad, una cantidad o un detalle que no aparece ni puede deducirse, decimos que el texto no permite saberlo.', 'No completes los datos ausentes con una suposición.',[
('Paula llevó una caja al club. Entre todos la abrieron y repartieron los libros que había dentro. Después acomodaron la caja vacía junto al estante.','¿Cuántos libros había en la caja?','El texto no permite saberlo','repartieron los libros que había dentro','Se mencionan libros, pero no se indica una cantidad.','Cinco','Diez'),
('Joaquín terminó la carrera y recibió una medalla. Su familia lo esperaba cerca de la llegada. Volvieron juntos a casa para descansar.','¿Qué edad tiene Joaquín?','El texto no permite saberlo','Joaquín terminó la carrera y recibió una medalla','Participar en una carrera no indica una edad exacta.','Once años','Quince años'),
('Lina abrió su paraguas al salir. Las gotas golpeaban la vereda y había charcos junto al cordón. Caminó despacio hasta la esquina.','¿De qué color era el paraguas?','El texto no permite saberlo','Lina abrió su paraguas al salir','La lluvia está apoyada por las gotas, pero el color no se menciona.','Azul','Rojo'),
('El grupo eligió un sendero y llegó a un mirador. Desde allí vio un río y varios árboles. Se sentó en un banco antes de regresar.','¿Qué vio desde el mirador?','Un río y varios árboles','Desde allí vio un río y varios árboles','Este dato sí está escrito: no hace falta inventarlo.','El texto no permite saberlo','El mar y un puerto'),
('El club organizó una feria el sábado. Abrió a las diez y cerró a las cuatro de la tarde. Varios vecinos ayudaron a ordenar al terminar.','¿A qué hora abrió la feria?','A las diez','Abrió a las diez','La hora de apertura está expresada en el texto.','El texto no permite saberlo','A las cuatro de la tarde'),
('Malena encontró una llave en el patio. La entregó en la oficina para que su dueño pudiera recuperarla. Al salir, volvió a jugar con sus amigas.','¿A quién pertenecía la llave?','El texto no permite saberlo','para que su dueño pudiera recuperarla','Se menciona a un dueño, pero no se lo identifica.','A Malena','A una de sus amigas')])
root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8');start='// R16: lectura con evidencia.';end='// FIN R16'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst LECTURA_R16 = '+json.dumps(U,ensure_ascii=False,indent=2)+""";
for (const unidad of LECTURA_R16) {
 const indice = UNIDADES_BASES.findIndex(u => u.id === unidad.despues_de);
 if (indice < 0) throw new Error('Falta el paso anterior de ' + unidad.id);
 UNIDADES_BASES.splice(indice + 1, 0, unidad);
}
for (const id of ['leng_lect_1_literal','leng_lect_2_inferencia','leng_lect_3_idea_central']) {
 const u=UNIDADES_BASES.find(u=>u.id===id);
 u.visual={tipo:'lectura',titulo:'Texto para releer',texto:u.ejemplo.split(' ¿')[0]};
 for (const a of u.actividades) {
  const partes=a.enunciado.split('\\n');
  if(partes.length>1){a.visual={tipo:'lectura',titulo:'Texto para releer',texto:partes[0]};a.enunciado=partes.slice(1).join('\\n');}
 }
}
"""+end+'\n\n';i=min(s.index(marker) for marker in ['// R17: idea principal y resumen.','// R18: escritura guiada.','export const TEMAS_BASES'] if marker in s);p.write_text(s[:i]+code+s[i:],encoding='utf-8');print(len(U),'unidades;',len(U)*6,'actividades')
